var ph = PhaseManager.get_current_phase_instance()
if ph == null or not ("active_fighter_id" in ph):
	return false
if str(ph.active_fighter_id) != "":
	return false
if node.get_node_or_null("AttackAssignmentDialog") != null:
	return false
var p = node.get_node_or_null("Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/FightSelectionPanel")
return p != null and p.visible

